import type {
  DepthDiffEvent,
  DepthSnapshot,
  OrderBookSnapshotView,
  OrderBookStatus,
  PriceLevel,
  RawLevel,
} from '../types';

/**
 * Maintains a single symbol's local order book in sync with Binance's
 * partial-book depth diff stream, following Binance's documented
 * "how to manage a local order book" procedure:
 *
 *  1. Buffer diff events while no snapshot has been applied yet.
 *  2. On snapshot: discard buffered events with `u <= lastUpdateId`. The
 *     first remaining event must satisfy `U <= lastUpdateId + 1 <= u`.
 *  3. Apply events in order as long as each event's `U === previous.u + 1`.
 *  4. If a gap is ever detected, mark the book `stale` and surface
 *     `needsResync() === true` without corrupting previously-applied state;
 *     the caller is expected to re-fetch a REST snapshot and call
 *     `applySnapshot` again.
 *
 * Design note: once the book is anything other than `'live'` (i.e.
 * `'uninitialized'` or `'stale'`), every incoming diff is buffered rather
 * than discarded. This matters for the `'stale'` case: the live WebSocket
 * keeps delivering ever-increasing update IDs while we wait for a fresh
 * REST snapshot, and we must not throw those away - otherwise the first
 * diff that arrives *after* the new snapshot would almost certainly look
 * like a fresh gap (its `U` would already be far past the new
 * `lastUpdateId + 1`), producing a stale/resync loop forever. Buffering
 * through the stale period lets `applySnapshot` replay exactly the same
 * discard/straddle/contiguous-replay procedure it uses for the initial
 * sync, which is what actually lets the book recover.
 *
 * Implementation is intentionally framework-agnostic (no network, no DOM)
 * so it can be unit tested in isolation and reused inside the SharedWorker.
 */
export class OrderBookManager {
  private _status: OrderBookStatus = 'uninitialized';
  private _needsResync = false;
  private lastUpdateId = 0;
  private updatedAt = 0;
  private bids = new Map<number, number>(); // price -> qty
  private asks = new Map<number, number>(); // price -> qty
  private buffer: DepthDiffEvent[] = [];

  constructor(public readonly symbol: string) {}

  get status(): OrderBookStatus {
    return this._status;
  }

  /** Buffer or apply a diff event depending on current sync state. */
  applyDiff(evt: DepthDiffEvent): void {
    if (this._status !== 'live') {
      // Not yet synced (uninitialized) or desynced (stale) - buffer until
      // the next applySnapshot can validate/replay against it.
      this.buffer.push(evt);
      return;
    }

    if (evt.u <= this.lastUpdateId) {
      // Old/duplicate event; Binance's guidance is to drop these entirely.
      return;
    }

    if (evt.U !== this.lastUpdateId + 1) {
      // Gap detected: do not touch book state, just flag for resync and
      // start buffering (this event included) for the eventual replay.
      this._status = 'stale';
      this._needsResync = true;
      this.buffer.push(evt);
      return;
    }

    this.applyLevels(evt);
    this.lastUpdateId = evt.u;
    this.updatedAt = evt.E;
  }

  /** Apply a REST snapshot and replay/validate buffered diffs against it. */
  applySnapshot(snapshot: DepthSnapshot): void {
    this.bids = new Map();
    this.asks = new Map();
    this.applyRawLevels(this.bids, snapshot.bids);
    this.applyRawLevels(this.asks, snapshot.asks);
    this.lastUpdateId = snapshot.lastUpdateId;
    this.updatedAt = Date.now();

    const remaining = this.buffer.filter((d) => d.u > this.lastUpdateId);
    this.buffer = [];

    if (remaining.length === 0) {
      this._status = 'live';
      this._needsResync = false;
      return;
    }

    const first = remaining[0];
    if (!(first.U <= this.lastUpdateId + 1 && this.lastUpdateId + 1 <= first.u)) {
      // The oldest surviving buffered event doesn't straddle this snapshot's
      // lastUpdateId - we can't safely replay. Keep the snapshot's book
      // state visible, flag for resync, and hold onto the buffer in case a
      // later snapshot can make use of it.
      this._status = 'stale';
      this._needsResync = true;
      this.buffer = remaining;
      return;
    }

    this.applyLevels(first);
    this.lastUpdateId = first.u;
    this.updatedAt = first.E;
    let prev = first;

    for (let i = 1; i < remaining.length; i++) {
      const next = remaining[i];
      if (next.U !== prev.u + 1) {
        this._status = 'stale';
        this._needsResync = true;
        this.buffer = remaining.slice(i);
        return;
      }
      this.applyLevels(next);
      this.lastUpdateId = next.u;
      this.updatedAt = next.E;
      prev = next;
    }

    this._status = 'live';
    this._needsResync = false;
  }

  /** True when the manager has detected a sequence gap and needs a fresh REST snapshot. */
  needsResync(): boolean {
    return this._needsResync;
  }

  getView(): OrderBookSnapshotView {
    const bids = this.sortedLevels(this.bids, 'desc');
    const asks = this.sortedLevels(this.asks, 'asc');
    const bestBid = bids[0] ?? null;
    const bestAsk = asks[0] ?? null;
    const spread = bestBid && bestAsk ? bestAsk.price - bestBid.price : null;
    return {
      symbol: this.symbol,
      status: this._status,
      lastUpdateId: this.lastUpdateId,
      bids,
      asks,
      bestBid,
      bestAsk,
      spread,
      updatedAt: this.updatedAt,
    };
  }

  getTopN(n: number): { bids: PriceLevel[]; asks: PriceLevel[] } {
    const view = this.getView();
    return { bids: view.bids.slice(0, n), asks: view.asks.slice(0, n) };
  }

  private applyLevels(evt: DepthDiffEvent): void {
    this.applyRawLevels(this.bids, evt.b);
    this.applyRawLevels(this.asks, evt.a);
  }

  private applyRawLevels(map: Map<number, number>, levels: RawLevel[]): void {
    for (const [priceStr, qtyStr] of levels) {
      const price = Number(priceStr);
      const qty = Number(qtyStr);
      if (qty === 0) {
        map.delete(price);
      } else {
        map.set(price, qty);
      }
    }
  }

  private sortedLevels(map: Map<number, number>, dir: 'asc' | 'desc'): PriceLevel[] {
    const entries: PriceLevel[] = Array.from(map.entries()).map(([price, qty]) => ({ price, qty }));
    entries.sort((a, b) => (dir === 'desc' ? b.price - a.price : a.price - b.price));
    return entries;
  }
}

export interface SubscribeFrame {
  method: 'SUBSCRIBE' | 'UNSUBSCRIBE';
  params: string[];
  id: number;
}

export interface SubscriptionManagerOptions {
  /** Binance caps outbound control messages at 5/sec per connection. */
  maxMessagesPerSecond?: number;
  /** Binance caps a single connection at 1024 streams. */
  maxStreamsPerConnection?: number;
  now?: () => number;
}

const DEFAULT_MAX_MESSAGES_PER_SECOND = 5;
const DEFAULT_MAX_STREAMS_PER_CONNECTION = 1024;
const RATE_WINDOW_MS = 1000;

/**
 * Tracks which streams are needed (ref-counted across many panel "owners"),
 * batches SUBSCRIBE/UNSUBSCRIBE frames to minimize message count, and
 * throttles outgoing frames to stay within Binance's rate limit.
 */
export class SubscriptionManager {
  private readonly maxMessagesPerSecond: number;
  private readonly maxStreamsPerConnection: number;
  private readonly now: () => number;

  /** stream -> set of owner ids currently referencing it. */
  private owners = new Map<string, Set<string>>();
  /** Streams newly activated since the last successful flush; need a SUBSCRIBE frame. */
  private pendingSubscribe = new Set<string>();
  /** Streams newly deactivated since the last successful flush; need an UNSUBSCRIBE frame. */
  private pendingUnsubscribe = new Set<string>();

  /** Timestamps (per `now()`) of frames sent within the current rolling window. */
  private sendTimestamps: number[] = [];
  private nextId = 1;

  constructor(opts: SubscriptionManagerOptions = {}) {
    this.maxMessagesPerSecond = opts.maxMessagesPerSecond ?? DEFAULT_MAX_MESSAGES_PER_SECOND;
    this.maxStreamsPerConnection = opts.maxStreamsPerConnection ?? DEFAULT_MAX_STREAMS_PER_CONNECTION;
    this.now = opts.now ?? (() => Date.now());
  }

  /** Returns false (and does nothing) if accepting a brand-new stream would exceed capacity. */
  subscribe(ownerId: string, stream: string): boolean {
    const existingOwners = this.owners.get(stream);
    const isBrandNewStream = !existingOwners || existingOwners.size === 0;

    if (isBrandNewStream && this.activeStreamCount >= this.maxStreamsPerConnection) {
      return false;
    }

    if (!existingOwners) {
      this.owners.set(stream, new Set([ownerId]));
    } else {
      existingOwners.add(ownerId);
    }

    if (isBrandNewStream) {
      // If this stream was queued for UNSUBSCRIBE (raced back to life before
      // the frame went out), cancel that instead of sending both frames.
      if (this.pendingUnsubscribe.has(stream)) {
        this.pendingUnsubscribe.delete(stream);
      } else {
        this.pendingSubscribe.add(stream);
      }
    }

    return true;
  }

  unsubscribe(ownerId: string, stream: string): void {
    const existingOwners = this.owners.get(stream);
    if (!existingOwners || !existingOwners.has(ownerId)) {
      return;
    }
    existingOwners.delete(ownerId);
    if (existingOwners.size === 0) {
      this.owners.delete(stream);
      if (this.pendingSubscribe.has(stream)) {
        // Never actually went out on the wire; just drop the intent.
        this.pendingSubscribe.delete(stream);
      } else {
        this.pendingUnsubscribe.add(stream);
      }
    }
  }

  get activeStreamCount(): number {
    return this.owners.size;
  }

  get pendingCount(): number {
    return this.pendingSubscribe.size + this.pendingUnsubscribe.size;
  }

  isAtCapacity(): boolean {
    return this.activeStreamCount >= this.maxStreamsPerConnection;
  }

  /** Attempt to flush queued frames, respecting the rolling-window rate limit. Returns the frames actually sent. */
  flush(): SubscribeFrame[] {
    const sent: SubscribeFrame[] = [];

    if (this.pendingSubscribe.size > 0 && this.tryRecordSend()) {
      sent.push({ method: 'SUBSCRIBE', params: Array.from(this.pendingSubscribe), id: this.nextId++ });
      this.pendingSubscribe = new Set();
    }

    if (this.pendingUnsubscribe.size > 0 && this.tryRecordSend()) {
      sent.push({ method: 'UNSUBSCRIBE', params: Array.from(this.pendingUnsubscribe), id: this.nextId++ });
      this.pendingUnsubscribe = new Set();
    }

    return sent;
  }

  /** Returns true (and records the send) if sending one more frame right now stays within the rate budget. */
  private tryRecordSend(): boolean {
    const now = this.now();
    this.sendTimestamps = this.sendTimestamps.filter((t) => now - t < RATE_WINDOW_MS);
    if (this.sendTimestamps.length >= this.maxMessagesPerSecond) {
      return false;
    }
    this.sendTimestamps.push(now);
    return true;
  }
}

export type Host = 'primary' | 'fallback';

export interface ReconnectPolicyOptions {
  baseDelayMs?: number;
  maxDelayMs?: number;
  jitterRatio?: number;
  /** Connection uptime after which a subsequent disconnect resets backoff to base. */
  stableAfterMs?: number;
  /** Proactively reconnect before Binance's own 24h forced-disconnect. */
  proactiveReconnectAfterMs?: number;
  maxPrimaryFailuresBeforeFallback?: number;
  /** Injectable RNG in [0, 1) for deterministic jitter in tests. */
  random?: () => number;
}

export interface FailureDecision {
  delayMs: number;
  nextHost: Host;
}

const DEFAULT_BASE_DELAY_MS = 1000;
const DEFAULT_MAX_DELAY_MS = 30_000;
const DEFAULT_JITTER_RATIO = 0.2;
const DEFAULT_STABLE_AFTER_MS = 60_000;
const DEFAULT_PROACTIVE_RECONNECT_AFTER_MS = 23.5 * 3600 * 1000;
const DEFAULT_MAX_PRIMARY_FAILURES_BEFORE_FALLBACK = 3;

/**
 * Exponential backoff + jitter + primary/fallback host selection +
 * proactive-reconnect scheduling ahead of Binance's 24h connection cap.
 */
export class ReconnectPolicy {
  private readonly baseDelayMs: number;
  private readonly maxDelayMs: number;
  private readonly jitterRatio: number;
  private readonly stableAfterMs: number;
  private readonly proactiveReconnectAfterMs: number;
  private readonly maxPrimaryFailuresBeforeFallback: number;
  private readonly random: () => number;

  /** Total consecutive failures (across hosts), used to compute the exponential backoff exponent. */
  private consecutiveFailures = 0;
  /** Consecutive *primary*-only failures, used to decide when to fall over to the fallback host. */
  private consecutivePrimaryFailures = 0;
  private currentHost: Host = 'primary';
  private connectedAtMs: number | null = null;

  constructor(opts: ReconnectPolicyOptions = {}) {
    this.baseDelayMs = opts.baseDelayMs ?? DEFAULT_BASE_DELAY_MS;
    this.maxDelayMs = opts.maxDelayMs ?? DEFAULT_MAX_DELAY_MS;
    this.jitterRatio = opts.jitterRatio ?? DEFAULT_JITTER_RATIO;
    this.stableAfterMs = opts.stableAfterMs ?? DEFAULT_STABLE_AFTER_MS;
    this.proactiveReconnectAfterMs = opts.proactiveReconnectAfterMs ?? DEFAULT_PROACTIVE_RECONNECT_AFTER_MS;
    this.maxPrimaryFailuresBeforeFallback =
      opts.maxPrimaryFailuresBeforeFallback ?? DEFAULT_MAX_PRIMARY_FAILURES_BEFORE_FALLBACK;
    this.random = opts.random ?? (() => Math.random());
  }

  recordFailure(host: Host): FailureDecision {
    this.consecutiveFailures += 1;

    if (host === 'primary') {
      this.consecutivePrimaryFailures += 1;
      if (this.consecutivePrimaryFailures >= this.maxPrimaryFailuresBeforeFallback) {
        this.currentHost = 'fallback';
      } else {
        this.currentHost = 'primary';
      }
    } else {
      // A fallback failure doesn't reset the primary-failure counter; we
      // simply stay on fallback and keep escalating the shared backoff.
      this.currentHost = 'fallback';
    }

    const exponent = this.consecutiveFailures - 1;
    const rawDelay = this.baseDelayMs * Math.pow(2, exponent);
    const cappedDelay = Math.min(rawDelay, this.maxDelayMs);

    // Jitter: +/- jitterRatio of the capped base delay. random() is in
    // [0, 1); map it to [-jitterRatio, +jitterRatio].
    const jitterSpan = cappedDelay * this.jitterRatio;
    const jitterOffset = (this.random() * 2 - 1) * jitterSpan;
    const delayMs = Math.min(this.maxDelayMs, Math.max(0, cappedDelay + jitterOffset));

    return { delayMs, nextHost: this.currentHost };
  }

  recordConnected(atMs: number): void {
    this.connectedAtMs = atMs;
  }

  recordDisconnected(atMs: number): void {
    if (this.connectedAtMs !== null) {
      const uptime = atMs - this.connectedAtMs;
      if (uptime >= this.stableAfterMs) {
        this.consecutiveFailures = 0;
        this.consecutivePrimaryFailures = 0;
      }
    }
    this.connectedAtMs = null;
  }

  shouldProactivelyReconnect(nowMs: number, connectedAtMs: number): boolean {
    return nowMs - connectedAtMs >= this.proactiveReconnectAfterMs;
  }

  reset(): void {
    this.consecutiveFailures = 0;
    this.consecutivePrimaryFailures = 0;
    this.currentHost = 'primary';
    this.connectedAtMs = null;
  }
}

/**
 * Ack-gated, latest-state-wins delivery gate for a single output port (one
 * browser window/panel). Guarantees at most one in-flight batch per port so
 * a slow/backgrounded window can never build an unbounded backlog or block
 * delivery to other windows sharing the same hub.
 */
export class PortBackpressureGate<T> {
  private _inFlight = false;
  private _lastSeqSent = 0;
  private pending: T | null = null;
  private hasPending = false;
  /** The `send` callback captured from the most recent `push()`, reused to flush a coalesced pending payload on ack. */
  private lastSend: ((payload: T, seq: number) => void) | null = null;

  constructor(_opts?: { maxInFlight?: number }) {
    // maxInFlight is reserved for future multi-in-flight support; this gate
    // always enforces at most one in-flight payload per port.
  }

  /** Queue a payload for delivery. Sends immediately if nothing is in flight; otherwise coalesces with any already-pending payload. */
  push(payload: T, send: (payload: T, seq: number) => void): void {
    this.lastSend = send;
    if (this._inFlight) {
      this.pending = payload;
      this.hasPending = true;
      return;
    }
    this._inFlight = true;
    this._lastSeqSent += 1;
    send(payload, this._lastSeqSent);
  }

  /** Acknowledge a previously-sent seq; flushes the latest pending payload, if any. */
  ack(seq: number): void {
    if (seq !== this._lastSeqSent) {
      // Stale/unknown ack - ignore.
      return;
    }
    if (this.hasPending && this.lastSend) {
      const payload = this.pending as T;
      this.pending = null;
      this.hasPending = false;
      this._lastSeqSent += 1;
      this.lastSend(payload, this._lastSeqSent);
      // stays in flight
    } else {
      this._inFlight = false;
    }
  }

  get inFlight(): boolean {
    return this._inFlight;
  }

  get lastSeqSent(): number {
    return this._lastSeqSent;
  }
}

/**
 * Primary/fallback Binance Spot production endpoints. No API key required
 * for any of these (public market data only).
 *
 * The fallback host (`data-api.binance.vision` / `data-stream.binance.vision`)
 * is Binance's documented mirror for regions where the primary
 * `binance.com` / `stream.binance.com` hosts are blocked. `ReconnectPolicy`
 * decides when to switch a connection over to the fallback.
 */
import type { Host } from '../connection/ReconnectPolicy';

export const REST_HOSTS: Record<Host, string> = {
  primary: 'https://api.binance.com',
  fallback: 'https://data-api.binance.vision',
};

export const WS_HOSTS: Record<Host, string> = {
  primary: 'wss://stream.binance.com:9443',
  fallback: 'wss://data-stream.binance.vision',
};

export function restBaseUrl(host: Host): string {
  return REST_HOSTS[host];
}

export function wsBaseUrl(host: Host): string {
  return WS_HOSTS[host];
}

/** Combined-stream control endpoint: streams are added/removed via SUBSCRIBE/UNSUBSCRIBE frames, not the URL. */
export function wsControlUrl(host: Host): string {
  return `${wsBaseUrl(host)}/ws`;
}

/**
 * Thin REST helpers for Binance Spot public market-data endpoints. No API
 * key is required for any of these. `fetch` is injectable so the hub (and
 * tests, if any land later) can swap in a fake without touching global
 * state - defaults to the real global `fetch`, which is available both on
 * the main thread and inside a SharedWorker.
 */
import type { Candle, DepthSnapshot, KlineInterval } from '../types';

export type FetchFn = typeof fetch;

export interface BinanceRestOptions {
  fetchFn?: FetchFn;
}

/** Raw shape of one row returned by `GET /api/v3/klines`. */
type RawKline = [
  number, // open time
  string, // open
  string, // high
  string, // low
  string, // close
  string, // volume
  number, // close time
  string, // quote asset volume
  number, // number of trades
  string, // taker buy base asset volume
  string, // taker buy quote asset volume
  string, // unused
];

async function getJson<T>(fetchFn: FetchFn, url: string): Promise<T> {
  const res = await fetchFn(url);
  if (!res.ok) {
    throw new Error(`Binance REST request failed: ${res.status} ${res.statusText} (${url})`);
  }
  return (await res.json()) as T;
}

/** `GET /api/v3/depth?symbol=<SYM>&limit=1000` - order book snapshot used to (re)sync a local OrderBookManager. */
export async function fetchDepthSnapshot(
  restBaseUrl: string,
  symbol: string,
  opts: BinanceRestOptions = {},
): Promise<DepthSnapshot> {
  const fetchFn = opts.fetchFn ?? fetch;
  const url = `${restBaseUrl}/api/v3/depth?symbol=${encodeURIComponent(symbol.toUpperCase())}&limit=1000`;
  const raw = await getJson<{ lastUpdateId: number; bids: [string, string][]; asks: [string, string][] }>(
    fetchFn,
    url,
  );
  return {
    lastUpdateId: raw.lastUpdateId,
    bids: raw.bids,
    asks: raw.asks,
  };
}

/**
 * `GET /api/v3/klines?symbol=<SYM>&interval=<I>&limit=500` - recent candle
 * history used to seed a chart panel before the live `kline` stream takes
 * over. Binance's raw kline REST row shape differs from the websocket
 * kline event shape (a flat array, not `{ k: {...} }`), so we map it
 * explicitly here.
 */
export async function fetchKlines(
  restBaseUrl: string,
  symbol: string,
  interval: KlineInterval,
  opts: BinanceRestOptions = {},
): Promise<Candle[]> {
  const fetchFn = opts.fetchFn ?? fetch;
  const url = `${restBaseUrl}/api/v3/klines?symbol=${encodeURIComponent(
    symbol.toUpperCase(),
  )}&interval=${interval}&limit=500`;
  const raw = await getJson<RawKline[]>(fetchFn, url);
  const now = Date.now();
  return raw.map((row) => {
    const [openTime, open, high, low, close, volume, closeTime] = row;
    return {
      openTime,
      closeTime,
      open: Number(open),
      high: Number(high),
      low: Number(low),
      close: Number(close),
      volume: Number(volume),
      // The most recent row from a REST kline query may be the
      // still-forming current candle; only rows whose closeTime has
      // already elapsed are guaranteed closed.
      closed: closeTime < now,
    };
  });
}

/**
 * DataHub - the orchestrator that lives inside the SharedWorker and is the
 * single owner of the one live Binance connection shared by every window
 * (main window + every pop-out) connected to this worker.
 *
 * Ownership:
 *  - One control WebSocket per logical connection, to `wss://<host>/ws`.
 *    We use the raw `/ws` endpoint (not `/stream?streams=...`) and manage
 *    membership dynamically via SUBSCRIBE/UNSUBSCRIBE control frames
 *    (`SubscriptionManager`) so changing symbols/panels never requires a
 *    full socket reconnect. Because `/ws` is used (not `/stream`), inbound
 *    payloads arrive UNWRAPPED (no `{stream, data}` envelope) - we route
 *    purely by the event's own `e` (and `s`) fields.
 *  - One `OrderBookManager` per subscribed symbol (depth).
 *  - One `TapeBuffer` (ring buffer) per subscribed symbol (aggTrade).
 *  - One latest-known `Candle` per subscribed (symbol, interval) (kline).
 *  - One shared `Map<symbol, WatchlistRow>` fed by the single global
 *    `!miniTicker@arr` stream (there is only ever at most one such stream
 *    for the whole hub, regardless of how many watchlist panels exist).
 *  - One `ReconnectPolicy` governing backoff + primary/fallback host choice
 *    + proactive reconnects ahead of Binance's 24h forced disconnect.
 *  - One `PortBackpressureGate` per (port, stream-kind+symbol[+interval])
 *    pair, so a slow/backgrounded window can never build backlog or block
 *    delivery to other windows. The pair is identified by a `gateKey`
 *    string, e.g. `depth:BTCUSDT`, `trades:ETHUSDT`, `candle:BTCUSDT:1m`,
 *    or the single shared `watchlist` key.
 *
 * Design trade-offs / known gaps (please read before extending):
 *
 *  1. Ack <-> gate routing. `protocol.ts`'s `AckMsg` only carries a bare
 *     `{ clientId, seq }` - it has no stream/subId to disambiguate WHICH
 *     gate an ack is for, yet each `PortBackpressureGate` independently
 *     numbers its own sends starting at 1 (by design/tests), so two gates
 *     on the same port can legitimately both be "waiting for ack of seq 1"
 *     at the same time. To avoid any risk of an ack for one stream
 *     spuriously flushing a different stream's gate, every outgoing
 *     message gets a **per-port globally unique "wire seq"** (independent
 *     of each gate's own internal counter), and the hub keeps a
 *     `wireSeq -> { gate, localSeq }` map per port. An incoming ack is
 *     looked up by wire seq and translated into a call to that *specific*
 *     gate's own `ack(localSeq)` - so stale/unknown wire seqs are ignored
 *     and never cross-talk between streams.
 *
 *  2. Reconnect re-subscribe strategy. Rather than trying to replay a
 *     stale `SubscriptionManager`'s pending/active bookkeeping across a
 *     brand new socket, we swap in a **fresh `SubscriptionManager`** on
 *     every successful (re)connect and re-seed it from our own
 *     `streamOwners` map (the hub's source of truth for "who currently
 *     wants this raw Binance stream"). This guarantees every logically-
 *     active stream gets a real SUBSCRIBE frame on the new socket, batched
 *     and rate-limited exactly like any other subscribe burst.
 *
 *  3. Trade tape delivery model. Rather than trying to deliver an
 *     exactly-once log of every individual `aggTrade` through the
 *     ack-gated gate (which is explicitly latest-state-wins, i.e. may
 *     coalesce/drop intermediate pushes for a slow consumer), each push to
 *     a trade-tape gate carries the **current full tape snapshot** (most
 *     recent N trades for that symbol, from a bounded `TapeBuffer`) rather
 *     than "only what changed since last ack". This keeps the semantics
 *     identical to every other stream the hub serves (order book, candle,
 *     watchlist are all "latest full state", not deltas) and means a
 *     backgrounded tape panel simply catches up to the latest N trades
 *     instead of silently losing prints with no way to notice. The
 *     trade-off: a panel that is behind by more than N trades will see a
 *     gap in trade IDs rather than every single print. N is
 *     `TRADE_BUFFER_SIZE` below.
 *
 *  4. Connection status is pushed via a direct `port.send(...)`, bypassing
 *     the backpressure gate entirely - `ConnectionStatusMsg` has no `seq`
 *     field (it isn't part of the ack-gated protocol), and it's an
 *     inherently low-frequency, latest-value-wins signal anyway.
 *
 *  5. Sharding past Binance's 1024-streams-per-connection cap is explicitly
 *     OUT OF SCOPE: the PRD's reference scenario (30 panels / 10 symbols)
 *     needs at most ~41 streams (10 depth + 10 aggTrade + up to ~20 kline
 *     intervals + 1 shared miniTicker-all), nowhere near the cap.
 *     `SubscriptionManager` already enforces the cap defensively
 *     (`subscribe()` returns `false` once truly full), but `DataHub` does
 *     not open a second WebSocket connection to shard across; it simply
 *     accepts the rejection. Multi-connection sharding would be the
 *     natural next step for a workstation that needs hundreds of symbols.
 *
 *  6. REST snapshot/kline-history fetch failures are logged and otherwise
 *     swallowed - the order book simply stays in its current
 *     `stale`/`uninitialized` status (visible to the trader) and will be
 *     retried the next time a gap is (re)detected or the connection
 *     (re)connects. There's no dedicated exponential-backoff retry loop
 *     purely for REST fetch failures; this piggybacks on the existing
 *     gap-detection/reconnect machinery rather than adding a second one.
 *
 *  7. Replay / fault injection seam. `setReplayMode` / `injectFault` below
 *     are intentionally-empty TODO integration points. The replay engine
 *     (`@core/replay/ReplayEngine`) and fault injector
 *     (`@core/replay/faultInjection`) are owned by a different workstream
 *     being built in parallel and are deliberately NOT imported here yet.
 *     There is also currently no wire message in `protocol.ts` for
 *     "enter replay mode" / "inject fault" - that's expected to be added
 *     alongside the integration that wires these up for real.
 */
import type {
  AggTradeEvent,
  Candle,
  DepthDiffEvent,
  KlineEvent,
  KlineInterval,
  MiniTickerEvent,
  StreamRef,
  Symbol,
  WatchlistRow,
} from '../types';
import { streamName as streamNameFor } from '../types';
import type {
  AckMsg,
  ByeMsg,
  ClientToHubMsg,
  ConnectionStatus,
  HelloMsg,
  HubPort,
  HubToClientMsg,
  SubscribeMsg,
  UnsubscribeMsg,
} from './protocol';
import { OrderBookManager } from '../orderbook/OrderBookManager';
import { SubscriptionManager } from '../connection/SubscriptionManager';
import { ReconnectPolicy, type Host } from '../connection/ReconnectPolicy';
import { PortBackpressureGate } from './PortBackpressureGate';
import { restBaseUrl, wsControlUrl } from './hosts';
import { fetchDepthSnapshot, fetchKlines, type FetchFn } from './binanceRest';
import { classifyTrade, TapeBuffer } from '../panels/tradeTape';
import { applyKlineEvent } from '../panels/candles';
import { applyMiniTicker } from '../panels/watchlist';

/** Most recent N trades kept per symbol, and the size of the snapshot pushed to trade-tape ports (see trade-off #3 above). */
const TRADE_BUFFER_SIZE = 200;
/** Flat USD-notional heuristic for highlighting large prints on the tape. */
const LARGE_TRADE_NOTIONAL_USD = 50_000;
/** How often we attempt to flush batched SUBSCRIBE/UNSUBSCRIBE frames and check for a due proactive reconnect. */
const FLUSH_INTERVAL_MS = 250;

interface WebSocketLike {
  readyState: number;
  send(data: string): void;
  close(code?: number, reason?: string): void;
  onopen: ((ev: unknown) => void) | null;
  onmessage: ((ev: { data: unknown }) => void) | null;
  onerror: ((ev: unknown) => void) | null;
  onclose: ((ev: unknown) => void) | null;
}

interface WebSocketCtorLike {
  new (url: string): WebSocketLike;
  readonly OPEN: number;
}

export interface DataHubOptions {
  /** Injectable WebSocket constructor; defaults to the real global `WebSocket` (present on the main thread and inside a SharedWorker). */
  webSocketImpl?: WebSocketCtorLike;
  /** Injectable fetch; defaults to the real global `fetch`. */
  fetchImpl?: FetchFn;
  /** Injectable clock, mainly for future deterministic testing. */
  now?: () => number;
  initialHost?: Host;
}

interface TrackedSubscription {
  clientId: string;
  subId: string;
  ref: StreamRef;
  gateKey: string;
  streamName: string;
}

interface PendingAckEntry {
  gate: PortBackpressureGate<unknown>;
  localSeq: number;
}

export class DataHub {
  private readonly webSocketImpl: WebSocketCtorLike;
  private readonly fetchImpl: FetchFn;
  private readonly now: () => number;

  private ws: WebSocketLike | null = null;
  private host: Host;
  private connStatus: ConnectionStatus = 'connecting';
  private connStatusSince: number;
  private connectedAtMs: number | null = null;

  private subscriptionManager = new SubscriptionManager();
  private readonly reconnectPolicy = new ReconnectPolicy();
  private flushTimer: ReturnType<typeof setInterval> | null = null;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;

  // --- Ports ----------------------------------------------------------
  private ports = new Map<string, HubPort>();
  private portGates = new Map<string, Map<string, PortBackpressureGate<unknown>>>();
  private portPendingAcks = new Map<string, Map<number, PendingAckEntry>>();
  private portNextWireSeq = new Map<string, number>();
  /** gateKey -> set of clientId currently interested in it (fan-out / broadcast target list). */
  private listeners = new Map<string, Set<string>>();
  /** clientId -> gateKey -> how many of this port's own subIds reference it. */
  private portGateRefCounts = new Map<string, Map<string, number>>();

  // --- Subscriptions / resources ---------------------------------------
  /** `${clientId}:${subId}` -> bookkeeping needed to clean up on unsubscribe/bye. */
  private subscriptions = new Map<string, TrackedSubscription>();
  /** Binance raw stream name -> set of `${clientId}:${subId}` owner keys currently wanting it. */
  private streamOwners = new Map<string, Set<string>>();
  private streamRefByName = new Map<string, StreamRef>();

  private orderBooks = new Map<Symbol, OrderBookManager>();
  private resyncInFlight = new Set<Symbol>();
  private tradeBuffers = new Map<Symbol, TapeBuffer>();
  private candles = new Map<string, Candle>(); // `${symbol}:${interval}` -> latest candle
  private watchlistRows = new Map<Symbol, WatchlistRow>();

  constructor(opts: DataHubOptions = {}) {
    this.webSocketImpl = opts.webSocketImpl ?? (WebSocket as unknown as WebSocketCtorLike);
    this.fetchImpl = opts.fetchImpl ?? ((...args: Parameters<FetchFn>) => fetch(...args));
    this.now = opts.now ?? (() => Date.now());
    this.host = opts.initialHost ?? 'primary';
    this.connStatusSince = this.now();

    this.flushTimer = setInterval(() => this.tick(), FLUSH_INTERVAL_MS);
    this.connect();
  }

  // ------------------------------------------------------------------
  // Public surface
  // ------------------------------------------------------------------

  handleClientMessage(port: HubPort, msg: ClientToHubMsg): void {
    switch (msg.type) {
      case 'hello':
        this.handleHello(port, msg);
        break;
      case 'subscribe':
        this.handleSubscribe(port, msg);
        break;
      case 'unsubscribe':
        this.handleUnsubscribe(msg);
        break;
      case 'ack':
        this.handleAck(msg);
        break;
      case 'bye':
        this.handleBye(msg);
        break;
    }
  }

  /** TODO(replay-integration): wire this up to `@core/replay/ReplayEngine` once `protocol.ts` grows a
   * client->hub message for it. When enabled, the hub should stop feeding `OrderBookManager`/trade/candle/
   * watchlist state from the live WebSocket and instead feed it from `ReplayEngine`'s `onEvent` callback,
   * at the given speed, while leaving every downstream broadcast/backpressure/ack path (below) untouched -
   * replay should be indistinguishable from "live" to a panel. */
  setReplayMode(_enabled: boolean, _speed?: number): void {
    console.info('[DataHub] setReplayMode is a documented no-op seam; replay engine integration is pending.');
  }

  /** TODO(fault-injection-integration): wire this up to `@core/replay/faultInjection` (e.g. `injectSequenceGap`)
   * once `protocol.ts` grows a client->hub message for it. `'dropConnection'` should call something equivalent
   * to `this.ws?.close()` to exercise the reconnect path; `'gap'` should shift a live/replayed depth diff's
   * update-id range for the given symbol before it reaches `OrderBookManager.applyDiff`, to exercise resync. */
  injectFault(_kind: 'dropConnection' | 'gap', _symbol?: Symbol): void {
    console.info('[DataHub] injectFault is a documented no-op seam; fault injection integration is pending.');
  }

  dispose(): void {
    if (this.flushTimer) clearInterval(this.flushTimer);
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    this.flushTimer = null;
    this.reconnectTimer = null;
    if (this.ws) {
      this.ws.onopen = null;
      this.ws.onmessage = null;
      this.ws.onerror = null;
      this.ws.onclose = null;
      this.ws.close();
      this.ws = null;
    }
    this.setConnStatus('offline');
  }

  // ------------------------------------------------------------------
  // Client message handlers
  // ------------------------------------------------------------------

  private handleHello(port: HubPort, msg: HelloMsg): void {
    this.ports.set(msg.clientId, port);
    port.send({ type: 'connectionStatus', status: this.connStatus, host: this.host, since: this.connStatusSince });
  }

  private handleSubscribe(port: HubPort, msg: SubscribeMsg): void {
    this.ports.set(msg.clientId, port);
    const subKey = `${msg.clientId}:${msg.subId}`;
    const ref = msg.ref;
    const gateKey = this.gateKeyFor(ref);
    const sName = streamNameFor(ref);

    this.subscriptions.set(subKey, { clientId: msg.clientId, subId: msg.subId, ref, gateKey, streamName: sName });
    this.addListener(gateKey, msg.clientId);
    this.bumpPortGateRefCount(msg.clientId, gateKey, 1);

    switch (ref.kind) {
      case 'depth': {
        const symbol = ref.symbol!;
        const isNew = !this.orderBooks.has(symbol);
        if (isNew) this.orderBooks.set(symbol, new OrderBookManager(symbol));
        this.addStreamOwner(sName, ref, subKey);
        if (isNew) {
          void this.syncOrderBook(symbol);
        } else {
          const manager = this.orderBooks.get(symbol)!;
          this.deliverTo(msg.clientId, gateKey, manager.getView(), (book, seq) => ({ type: 'orderBook', seq, book }));
        }
        break;
      }
      case 'aggTrade': {
        const symbol = ref.symbol!;
        if (!this.tradeBuffers.has(symbol)) this.tradeBuffers.set(symbol, new TapeBuffer(TRADE_BUFFER_SIZE));
        this.addStreamOwner(sName, ref, subKey);
        const buf = this.tradeBuffers.get(symbol)!;
        if (buf.entries.length > 0) {
          this.deliverTo(msg.clientId, gateKey, buf.entries, (trades, seq) => ({ type: 'trades', seq, symbol, trades }));
        }
        break;
      }
      case 'kline': {
        const symbol = ref.symbol!;
        const interval = ref.interval!;
        const key = `${symbol}:${interval}`;
        const isNew = !this.candles.has(key);
        this.addStreamOwner(sName, ref, subKey);
        if (isNew) {
          void this.seedCandleHistory(symbol, interval);
        } else {
          const candle = this.candles.get(key);
          if (candle) this.deliverTo(msg.clientId, gateKey, candle, (c, seq) => ({ type: 'candle', seq, symbol, candle: c }));
        }
        break;
      }
      case 'miniTicker':
      case 'miniTickerAll': {
        this.addStreamOwner(sName, ref, subKey);
        if (this.watchlistRows.size > 0) {
          this.deliverTo(msg.clientId, gateKey, Array.from(this.watchlistRows.values()), (rows, seq) => ({
            type: 'watchlist',
            seq,
            rows,
          }));
        }
        break;
      }
    }

    this.flushSubscriptions();
  }

  private handleUnsubscribe(msg: UnsubscribeMsg): void {
    const subKey = `${msg.clientId}:${msg.subId}`;
    const sub = this.subscriptions.get(subKey);
    if (!sub) return;
    this.subscriptions.delete(subKey);
    this.bumpPortGateRefCount(msg.clientId, sub.gateKey, -1);
    this.removeStreamOwner(sub.streamName, subKey);
    this.flushSubscriptions();
  }

  private handleAck(msg: AckMsg): void {
    const pendingMap = this.portPendingAcks.get(msg.clientId);
    if (!pendingMap) return;
    const entry = pendingMap.get(msg.seq);
    if (!entry) return; // stale/unknown wire seq - ignore.
    pendingMap.delete(msg.seq);
    entry.gate.ack(entry.localSeq);
  }

  private handleBye(msg: ByeMsg): void {
    for (const subKey of Array.from(this.subscriptions.keys())) {
      if (!subKey.startsWith(`${msg.clientId}:`)) continue;
      const sub = this.subscriptions.get(subKey);
      if (sub) this.handleUnsubscribe({ type: 'unsubscribe', clientId: msg.clientId, subId: sub.subId });
    }
    this.ports.delete(msg.clientId);
    this.portGates.delete(msg.clientId);
    this.portGateRefCounts.delete(msg.clientId);
    this.portPendingAcks.delete(msg.clientId);
    this.portNextWireSeq.delete(msg.clientId);
  }

  // ------------------------------------------------------------------
  // Fan-out bookkeeping
  // ------------------------------------------------------------------

  private gateKeyFor(ref: StreamRef): string {
    switch (ref.kind) {
      case 'depth':
        return `depth:${ref.symbol}`;
      case 'aggTrade':
        return `trades:${ref.symbol}`;
      case 'kline':
        return `candle:${ref.symbol}:${ref.interval}`;
      case 'miniTicker':
      case 'miniTickerAll':
        return 'watchlist';
    }
  }

  private addListener(gateKey: string, clientId: string): void {
    let set = this.listeners.get(gateKey);
    if (!set) {
      set = new Set();
      this.listeners.set(gateKey, set);
    }
    set.add(clientId);
  }

  private removeListener(gateKey: string, clientId: string): void {
    const set = this.listeners.get(gateKey);
    if (!set) return;
    set.delete(clientId);
    if (set.size === 0) this.listeners.delete(gateKey);
  }

  private bumpPortGateRefCount(clientId: string, gateKey: string, delta: number): void {
    let m = this.portGateRefCounts.get(clientId);
    if (!m) {
      m = new Map();
      this.portGateRefCounts.set(clientId, m);
    }
    const next = (m.get(gateKey) ?? 0) + delta;
    if (next <= 0) {
      m.delete(gateKey);
      this.removeListener(gateKey, clientId);
      this.portGates.get(clientId)?.delete(gateKey);
    } else {
      m.set(gateKey, next);
    }
  }

  private addStreamOwner(streamName: string, ref: StreamRef, ownerKey: string): void {
    this.streamRefByName.set(streamName, ref);
    let owners = this.streamOwners.get(streamName);
    if (!owners) {
      owners = new Set();
      this.streamOwners.set(streamName, owners);
    }
    owners.add(ownerKey);
    this.subscriptionManager.subscribe(ownerKey, streamName);
  }

  private removeStreamOwner(streamName: string, ownerKey: string): void {
    const owners = this.streamOwners.get(streamName);
    if (!owners) return;
    owners.delete(ownerKey);
    this.subscriptionManager.unsubscribe(ownerKey, streamName);
    if (owners.size === 0) {
      this.streamOwners.delete(streamName);
      this.disposeResourceForStream(streamName);
    }
  }

  private disposeResourceForStream(streamName: string): void {
    const ref = this.streamRefByName.get(streamName);
    this.streamRefByName.delete(streamName);
    if (!ref) return;
    switch (ref.kind) {
      case 'depth':
        this.orderBooks.delete(ref.symbol!);
        this.resyncInFlight.delete(ref.symbol!);
        break;
      case 'aggTrade':
        this.tradeBuffers.delete(ref.symbol!);
        break;
      case 'kline':
        this.candles.delete(`${ref.symbol}:${ref.interval}`);
        break;
      case 'miniTicker':
      case 'miniTickerAll':
        // Single shared global stream; harmless/cheap to keep cached rows around.
        break;
    }
  }

  // ------------------------------------------------------------------
  // Delivery (ack-gated, per port+stream)
  // ------------------------------------------------------------------

  private deliverTo<T>(
    clientId: string,
    gateKey: string,
    payload: T,
    buildMsg: (payload: T, seq: number) => HubToClientMsg,
  ): void {
    const port = this.ports.get(clientId);
    if (!port) return;

    let gatesForPort = this.portGates.get(clientId);
    if (!gatesForPort) {
      gatesForPort = new Map();
      this.portGates.set(clientId, gatesForPort);
    }
    let gate = gatesForPort.get(gateKey) as PortBackpressureGate<T> | undefined;
    if (!gate) {
      gate = new PortBackpressureGate<T>();
      gatesForPort.set(gateKey, gate as PortBackpressureGate<unknown>);
    }

    gate.push(payload, (p, localSeq) => {
      const wireSeq = this.nextWireSeq(clientId);
      let pendingMap = this.portPendingAcks.get(clientId);
      if (!pendingMap) {
        pendingMap = new Map();
        this.portPendingAcks.set(clientId, pendingMap);
      }
      pendingMap.set(wireSeq, { gate: gate as unknown as PortBackpressureGate<unknown>, localSeq });
      port.send(buildMsg(p, wireSeq));
    });
  }

  private broadcastToGateKey<T>(
    gateKey: string,
    payload: T,
    buildMsg: (payload: T, seq: number) => HubToClientMsg,
  ): void {
    const clientIds = this.listeners.get(gateKey);
    if (!clientIds || clientIds.size === 0) return;
    for (const clientId of clientIds) this.deliverTo(clientId, gateKey, payload, buildMsg);
  }

  private nextWireSeq(clientId: string): number {
    const next = (this.portNextWireSeq.get(clientId) ?? 0) + 1;
    this.portNextWireSeq.set(clientId, next);
    return next;
  }

  // ------------------------------------------------------------------
  // REST sync helpers
  // ------------------------------------------------------------------

  private async syncOrderBook(symbol: Symbol): Promise<void> {
    if (this.resyncInFlight.has(symbol)) return;
    this.resyncInFlight.add(symbol);
    try {
      const snapshot = await fetchDepthSnapshot(restBaseUrl(this.host), symbol, { fetchFn: this.fetchImpl });
      const manager = this.orderBooks.get(symbol);
      if (!manager) return; // unsubscribed while the fetch was in flight.
      manager.applySnapshot(snapshot);
      this.broadcastOrderBook(symbol);
    } catch (err) {
      console.error(`[DataHub] failed to fetch depth snapshot for ${symbol}:`, err);
    } finally {
      this.resyncInFlight.delete(symbol);
    }
  }

  private broadcastOrderBook(symbol: Symbol): void {
    const manager = this.orderBooks.get(symbol);
    if (!manager) return;
    this.broadcastToGateKey(`depth:${symbol}`, manager.getView(), (book, seq) => ({ type: 'orderBook', seq, book }));
  }

  private async seedCandleHistory(symbol: Symbol, interval: KlineInterval): Promise<void> {
    const key = `${symbol}:${interval}`;
    try {
      const history = await fetchKlines(restBaseUrl(this.host), symbol, interval, { fetchFn: this.fetchImpl });
      if (!this.streamOwners.has(streamNameFor({ kind: 'kline', symbol, interval }))) return; // unsubscribed meanwhile
      const latest = history[history.length - 1];
      if (!latest) return;
      this.candles.set(key, latest);
      this.broadcastToGateKey(`candle:${symbol}:${interval}`, latest, (c, seq) => ({ type: 'candle', seq, symbol, candle: c }));
    } catch (err) {
      console.error(`[DataHub] failed to fetch kline history for ${symbol} ${interval}:`, err);
    }
  }

  // ------------------------------------------------------------------
  // WebSocket lifecycle
  // ------------------------------------------------------------------

  private connect(): void {
    let socket: WebSocketLike;
    try {
      socket = new this.webSocketImpl(wsControlUrl(this.host));
    } catch (err) {
      console.error('[DataHub] failed to construct WebSocket:', err);
      this.handleConnectionFailure();
      return;
    }
    this.ws = socket;
    socket.onopen = () => this.onSocketOpen();
    socket.onmessage = (ev: { data: unknown }) => {
      const data = ev.data;
      this.handleSocketMessage(typeof data === 'string' ? data : String(data));
    };
    socket.onerror = () => {
      /* onclose always follows onerror for browser/worker WebSocket; nothing extra to do here. */
    };
    socket.onclose = () => this.onSocketClose();
  }

  private onSocketOpen(): void {
    const now = this.now();
    this.connectedAtMs = now;
    this.reconnectPolicy.recordConnected(now);
    this.setConnStatus('live');

    // Fresh SubscriptionManager so every currently-wanted stream is treated as
    // newly-needed again and gets a SUBSCRIBE frame batched onto this new
    // socket (see trade-off #2 at the top of this file).
    this.subscriptionManager = new SubscriptionManager();
    for (const [sName, owners] of this.streamOwners) {
      for (const ownerKey of owners) this.subscriptionManager.subscribe(ownerKey, sName);
    }
    this.flushSubscriptions();

    // Binance requires a fresh REST snapshot after any disconnect/reconnect.
    for (const symbol of this.orderBooks.keys()) void this.syncOrderBook(symbol);
  }

  private onSocketClose(): void {
    if (this.ws) {
      this.ws.onopen = null;
      this.ws.onmessage = null;
      this.ws.onerror = null;
      this.ws.onclose = null;
    }
    this.ws = null;
    this.handleConnectionFailure();
  }

  private handleConnectionFailure(): void {
    const now = this.now();
    if (this.connectedAtMs !== null) {
      this.reconnectPolicy.recordDisconnected(now);
    }
    this.connectedAtMs = null;
    this.setConnStatus('reconnecting');

    const decision = this.reconnectPolicy.recordFailure(this.host);
    this.host = decision.nextHost;
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    this.reconnectTimer = setTimeout(() => this.connect(), decision.delayMs);
  }

  private proactiveReconnect(): void {
    console.info('[DataHub] proactively reconnecting ahead of Binance\u2019s 24h forced-disconnect window.');
    this.reconnectPolicy.reset();
    this.host = 'primary';
    this.ws?.close();
    // onSocketClose -> handleConnectionFailure will schedule the actual reconnect at base delay.
  }

  private tick(): void {
    this.flushSubscriptions();
    if (this.connectedAtMs !== null && this.reconnectPolicy.shouldProactivelyReconnect(this.now(), this.connectedAtMs)) {
      this.proactiveReconnect();
    }
  }

  private flushSubscriptions(): void {
    if (!this.ws || this.ws.readyState !== this.webSocketImpl.OPEN) return;
    const frames = this.subscriptionManager.flush();
    for (const frame of frames) {
      this.ws.send(JSON.stringify(frame));
    }
  }

  private setConnStatus(status: ConnectionStatus): void {
    if (this.connStatus === status) return;
    this.connStatus = status;
    this.connStatusSince = this.now();
    const msg: HubToClientMsg = { type: 'connectionStatus', status, host: this.host, since: this.connStatusSince };
    for (const port of this.ports.values()) port.send(msg);
  }

  // ------------------------------------------------------------------
  // Inbound WebSocket message routing (by `e` field - see header comment)
  // ------------------------------------------------------------------

  private handleSocketMessage(raw: string): void {
    let data: unknown;
    try {
      data = JSON.parse(raw);
    } catch {
      return;
    }

    if (Array.isArray(data)) {
      this.handleMiniTickerArray(data as MiniTickerEvent[]);
      return;
    }
    if (typeof data !== 'object' || data === null || !('e' in data)) {
      // SUBSCRIBE/UNSUBSCRIBE control-frame ack (`{ result, id }`) or unrecognized payload.
      return;
    }

    const evt = data as { e: string };
    switch (evt.e) {
      case 'depthUpdate':
        this.handleDepthUpdate(data as DepthDiffEvent);
        break;
      case 'aggTrade':
        this.handleAggTrade(data as AggTradeEvent);
        break;
      case 'kline':
        this.handleKline(data as KlineEvent);
        break;
      case '24hrMiniTicker':
        this.handleMiniTickerArray([data as MiniTickerEvent]);
        break;
      default:
        break;
    }
  }

  private handleDepthUpdate(evt: DepthDiffEvent): void {
    const manager = this.orderBooks.get(evt.s);
    if (!manager) return;
    manager.applyDiff(evt);
    if (manager.needsResync()) {
      void this.syncOrderBook(evt.s);
    }
    this.broadcastOrderBook(evt.s);
  }

  private handleAggTrade(evt: AggTradeEvent): void {
    const buffer = this.tradeBuffers.get(evt.s);
    if (!buffer) return;
    const entry = classifyTrade(evt, LARGE_TRADE_NOTIONAL_USD);
    buffer.push(entry);
    this.broadcastToGateKey(`trades:${evt.s}`, buffer.entries, (trades, seq) => ({
      type: 'trades',
      seq,
      symbol: evt.s,
      trades,
    }));
  }

  private handleKline(evt: KlineEvent): void {
    const key = `${evt.s}:${evt.k.i}`;
    if (!this.candles.has(key) && !this.streamOwners.has(streamNameFor({ kind: 'kline', symbol: evt.s, interval: evt.k.i }))) {
      return;
    }
    const candle = applyKlineEvent(this.candles.get(key) ?? null, evt);
    this.candles.set(key, candle);
    this.broadcastToGateKey(`candle:${evt.s}:${evt.k.i}`, candle, (c, seq) => ({
      type: 'candle',
      seq,
      symbol: evt.s,
      candle: c,
    }));
  }

  private handleMiniTickerArray(events: MiniTickerEvent[]): void {
    for (const evt of events) {
      this.watchlistRows.set(evt.s, applyMiniTicker(evt));
    }
    if ((this.listeners.get('watchlist')?.size ?? 0) > 0) {
      this.broadcastToGateKey('watchlist', Array.from(this.watchlistRows.values()), (rows, seq) => ({
        type: 'watchlist',
        seq,
        rows,
      }));
    }
  }
}

/**
 * SharedWorker entry point. This is the one process every window (main
 * window + every pop-out) connects to, so there is exactly one Binance
 * WebSocket connection for the whole app regardless of how many windows
 * are open - each window just opens its own `MessagePort` into this same
 * worker (see `createDataHubClient.ts` on the main-thread side).
 *
 * This file intentionally contains almost no logic of its own: it adapts
 * the raw `MessagePort` API into the `HubPort` contract (`protocol.ts`)
 * and hands everything off to the single shared `DataHub` instance, which
 * owns the actual WebSocket/REST/order-book/backpressure machinery.
 */
import type { ClientToHubMsg, HubPort, HubToClientMsg } from '../core/hub/protocol';
import { DataHub } from '../core/hub/DataHub';

declare const self: SharedWorkerGlobalScope;

// One DataHub for the lifetime of this worker, shared by every connected port.
const dataHub = new DataHub();

self.onconnect = (event: MessageEvent) => {
  const port = event.ports[0];
  if (!port) return;

  // The HubPort wrapper needs a `clientId` up front, but we only learn it
  // from the first message a client sends (always a `hello`, carrying its
  // own `clientId`) - every `ClientToHubMsg` variant carries `clientId`,
  // so we can construct the wrapper lazily on first message and reuse it
  // for the remaining lifetime of this port.
  let hubPort: HubPort | null = null;

  port.onmessage = (ev: MessageEvent<ClientToHubMsg>) => {
    const msg = ev.data;
    if (!hubPort) {
      const clientId = msg.clientId;
      hubPort = {
        clientId,
        send: (outgoing: HubToClientMsg) => port.postMessage(outgoing),
      };
    }
    dataHub.handleClientMessage(hubPort, msg);
  };

  port.start();
};

/**
 * Main-thread implementation of `DataHubClient` (see `DataHubClient.ts`,
 * immutable). Opens one `SharedWorker` port - shared with every other
 * window at the same origin, including pop-outs - and layers a typed
 * subscribe/callback API plus automatic ack-on-receive on top of the raw
 * `ClientToHubMsg` / `HubToClientMsg` wire protocol (`protocol.ts`,
 * immutable).
 *
 * Known protocol-level gap (can't be fixed from this file - `protocol.ts`
 * is a stable shared contract owned elsewhere): `CandleUpdateMsg` carries
 * `symbol` but not `interval`. If a single window subscribes to two
 * different intervals of the *same* symbol at the same time, incoming
 * candle messages can't be disambiguated by interval here, so both
 * callbacks would receive every candle update for that symbol regardless
 * of interval. This is a pre-existing protocol limitation (not introduced
 * by this file); a real fix would add an `interval` field to
 * `CandleUpdateMsg`. In the common case of one chart interval per symbol
 * per window this never manifests.
 */
import type { DataHubClient } from './DataHubClient';
import type { ClientToHubMsg, ConnectionStatus, HubToClientMsg } from './protocol';
import type {
  Candle,
  KlineInterval,
  OrderBookSnapshotView,
  StreamRef,
  Symbol,
  TradeTapeEntry,
  WatchlistRow,
} from '../types';

type Unsubscribe = () => void;

export function createDataHubClient(windowRole: 'main' | 'popout' = 'main'): DataHubClient {
  const clientId = crypto.randomUUID();

  const worker = new SharedWorker(new URL('../../worker/dataHub.worker.ts', import.meta.url), {
    type: 'module',
    name: 'trading-workstation-data-hub',
  });
  const port = worker.port;

  let connectionStatus: ConnectionStatus = 'connecting';
  const statusListeners = new Set<(status: ConnectionStatus) => void>();

  /** streamKey -> subId -> raw hub message callback. A streamKey can have several subIds (several panels watching the same thing on this port). */
  const callbacksByStreamKey = new Map<string, Map<string, (msg: HubToClientMsg) => void>>();

  function send(msg: ClientToHubMsg): void {
    port.postMessage(msg);
  }

  function streamKeyForRef(ref: StreamRef): string {
    switch (ref.kind) {
      case 'depth':
        return `depth:${ref.symbol}`;
      case 'aggTrade':
        return `trades:${ref.symbol}`;
      case 'kline':
        // NOTE: intentionally symbol-only - see the protocol-gap note at the top of this file.
        return `candle:${ref.symbol}`;
      case 'miniTicker':
      case 'miniTickerAll':
        return 'watchlist';
    }
  }

  function streamKeyForIncoming(msg: HubToClientMsg): string | null {
    switch (msg.type) {
      case 'orderBook':
        return `depth:${msg.book.symbol}`;
      case 'trades':
        return `trades:${msg.symbol}`;
      case 'candle':
        return `candle:${msg.symbol}`;
      case 'watchlist':
        return 'watchlist';
      default:
        return null;
    }
  }

  function registerSubscription(ref: StreamRef, onRaw: (msg: HubToClientMsg) => void): Unsubscribe {
    const subId = crypto.randomUUID();
    const streamKey = streamKeyForRef(ref);
    let bucket = callbacksByStreamKey.get(streamKey);
    if (!bucket) {
      bucket = new Map();
      callbacksByStreamKey.set(streamKey, bucket);
    }
    bucket.set(subId, onRaw);

    send({ type: 'subscribe', clientId, subId, ref });

    let unsubscribed = false;
    return () => {
      if (unsubscribed) return;
      unsubscribed = true;
      const b = callbacksByStreamKey.get(streamKey);
      if (b) {
        b.delete(subId);
        if (b.size === 0) callbacksByStreamKey.delete(streamKey);
      }
      send({ type: 'unsubscribe', clientId, subId });
    };
  }

  port.onmessage = (ev: MessageEvent<HubToClientMsg>) => {
    const msg = ev.data;

    if (msg.type === 'connectionStatus') {
      connectionStatus = msg.status;
      for (const listener of statusListeners) listener(msg.status);
      return; // not part of the ack-gated/seq protocol - nothing to ack.
    }

    if (msg.type === 'error') {
      console.error(`[DataHubClient] hub error (${msg.recoverable ? 'recoverable' : 'fatal'}): ${msg.message}`);
      return;
    }

    // msg is now OrderBookUpdateMsg | TradesUpdateMsg | CandleUpdateMsg | WatchlistUpdateMsg - all carry `seq`.
    const streamKey = streamKeyForIncoming(msg);
    const bucket = streamKey ? callbacksByStreamKey.get(streamKey) : undefined;
    if (bucket) {
      for (const cb of bucket.values()) cb(msg);
    }

    // Ack immediately after invoking callback(s) so the hub's
    // PortBackpressureGate is freed for the next update. Heavy rendering
    // work happens later, inside each panel's own requestAnimationFrame
    // loop, decoupled from this ack.
    send({ type: 'ack', clientId, seq: msg.seq });
  };

  send({ type: 'hello', clientId, windowRole });

  const client: DataHubClient = {
    clientId,

    subscribeOrderBook(symbol: Symbol, onUpdate: (book: OrderBookSnapshotView) => void): Unsubscribe {
      return registerSubscription({ kind: 'depth', symbol }, (msg) => {
        if (msg.type === 'orderBook') onUpdate(msg.book);
      });
    },

    subscribeTrades(symbol: Symbol, onUpdate: (trades: TradeTapeEntry[]) => void): Unsubscribe {
      return registerSubscription({ kind: 'aggTrade', symbol }, (msg) => {
        if (msg.type === 'trades') onUpdate(msg.trades);
      });
    },

    subscribeCandles(symbol: Symbol, interval: KlineInterval, onUpdate: (candle: Candle) => void): Unsubscribe {
      return registerSubscription({ kind: 'kline', symbol, interval }, (msg) => {
        if (msg.type === 'candle') onUpdate(msg.candle);
      });
    },

    subscribeWatchlist(onUpdate: (rows: WatchlistRow[]) => void): Unsubscribe {
      return registerSubscription({ kind: 'miniTickerAll' }, (msg) => {
        if (msg.type === 'watchlist') onUpdate(msg.rows);
      });
    },

    onConnectionStatus(cb: (status: ConnectionStatus) => void): Unsubscribe {
      statusListeners.add(cb);
      return () => statusListeners.delete(cb);
    },

    getConnectionStatus(): ConnectionStatus {
      return connectionStatus;
    },

    setReplayMode(enabled: boolean, speed?: number): void {
      // TODO(replay-integration): protocol.ts has no client->hub message
      // for this yet. Once added, this should `send({ type: 'setReplayMode', enabled, speed })`
      // and the hub-side `DataHub.setReplayMode` seam should drive `@core/replay/ReplayEngine`.
      console.info(
        `[DataHubClient] setReplayMode(${enabled}, speed=${speed ?? 1}) is a documented no-op; replay engine integration is pending.`,
      );
    },

    injectFault(kind: 'dropConnection' | 'gap', symbol?: Symbol): void {
      // TODO(fault-injection-integration): protocol.ts has no client->hub
      // message for this yet. Once added, this should `send({ type: 'injectFault', kind, symbol })`
      // driving `@core/replay/faultInjection` on the hub side.
      console.info(
        `[DataHubClient] injectFault(${kind}${symbol ? `, ${symbol}` : ''}) is a documented no-op; fault injection integration is pending.`,
      );
    },

    dispose(): void {
      send({ type: 'bye', clientId });
      port.close();
    },
  };

  return client;
}

